const features = [
{ icon: 'i-lucide-boxes', number: '01', title: 'A home for every module.', text: 'Compose your application explicitly. Keep business services in plain Go and adapters at the edges.', link: 'modules', label: 'Explore modules' },
{ icon: 'i-lucide-braces', number: '02', title: 'Your types. Your contract.', text: 'Typed request and response schemas, validation, and OpenAPI 3.1 describe the API you actually build.', link: 'http', label: 'Discover typed HTTP' },
{ icon: 'i-lucide-workflow', number: '03', title: 'Add what you need.', text: 'Start with HTTP. Bring in GORM, migrations or gRPC when your application calls for them.', link: 'architecture', label: 'See the architecture' }
]
